&lt;/li&gt;
&lt;li data-local-id=&quot;e3ce559b-40f3-4076-bc1b-c81a504a5c92&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
